  frame.removeAllViews();ImageView image=new ImageView(this);image.setImageBitmap(bitmap);image.setScaleType(ImageView.ScaleType.FIT_CENTER);
  frame.addView(image,new FrameLayout.LayoutParams(dp(34),dp(34)));
